#include<bits/stdc++.h>
using namespace std;
//この問題で扱う整数は最大4×10^12であり、int型の上限を超えるため、long longを用いる。
//実装の簡略化のためlong longをllとして使えるようにする。（以下、llという型はlong long型と同じ）
using ll = long long;

//コピペする場合はここから～
//Era(n)を呼んだ後、isprime[i]=iが素数かどうか　となっている。
vector < bool > isprime;
//返り値は素数のリスト。
vector < ll > Era(int n) {
	isprime.resize(n, true);
	vector < ll > res;
	isprime[0] = false;
	isprime[1] = false;
	for(ll i = 2; i < n; ++i) isprime[i] = true;
	for(ll i = 2; i < n; ++i) {
		if(isprime[i]) {
			res.push_back(i);
			for(ll j = i * 2; j < n; j += i) isprime[j] = false;
		}
	}
	return res;
}
//コピペする場合は～ここまで

int main(){
	ll n;
	cin >> n;
	vector<ll> v = Era(1000005);
	ll ans{};
	for(ll p:v){
		if(p*p*p*p>n)break;
		//オーバーフロー対策
		if(p<100){
			//pow関数は誤差が出ることに注意。8乗程度ならこうやって書いた方が安全（ただし数え間違いの危険はある）
			if(p*p*p*p*p*p*p*p<=n)ans++;
		}
		for(ll q:v){
			if(q<=p)continue;
			if(p*p*q*q<=n){
				ans++;
			}
			else{
				break;
			}
		}
	}
	cout << ans << endl;
	return 0;
}
